
const pages=[...document.querySelectorAll('.section')], navButtons=[...document.querySelectorAll('[data-page]')];
function go(page){pages.forEach(p=>p.classList.toggle('active',p.id==='page-'+page));navButtons.forEach(b=>b.classList.toggle('active',b.dataset.page===page));const locationPanel=document.getElementById('globalLocationPanel');if(locationPanel)locationPanel.hidden=page!=='home';window.scrollTo({top:0,behavior:'smooth'});}
navButtons.forEach(b=>b.addEventListener('click',()=>{go(b.dataset.page);if(b.dataset.page==='weather')checkCycloneStatus()}));
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.style.display='block';setTimeout(()=>t.style.display='none',2600)}
const answers=[
[/irrigat|water|irrigation/i,"Check moisture at the crop’s active root depth, consider recent rainfall and the crop growth stage, then compare against locally recommended thresholds. This demo cannot determine a real irrigation need without verified field data."],
[/moisture|soil|estimate|accurac/i,"For better soil-moisture accuracy, combine calibrated ground measurements with soil type, measurement depth, rainfall and weather data. Satellite products are useful context but may be too coarse for an individual small plot. Validate predictions against independent field readings."],
[/tomato|spot|disease|leaf|fung/i,"Take a clear photo of both sides of the leaf and note crop age, recent weather and how symptoms spread. Several diseases and nutrient issues look similar; use a validated diagnostic model or consult a local agricultural expert before treatment."],
[/weather|rain/i,"The weather displayed here is sample data only. Connect a trusted weather API for a local forecast, and account for expected rainfall before scheduling irrigation."],
[/hello|hi|namaste/i,"Namaste! 🌱 I can help explain soil data, irrigation planning and crop-health checks. Tell me the crop, soil type and what you observed."]
];
function reply(q){for(const [re,a] of answers)if(re.test(q))return a;return "I can help with soil moisture, irrigation, weather inputs and crop-health checks. For a reliable recommendation, share the crop, soil type, recent rainfall and any measured soil-moisture value. This prototype is not connected to a live AI model."}
async function addChat(q){const log=document.getElementById('mainChat');if(!log)return;const u=document.createElement('div');u.className='bubble user';u.textContent=q;log.appendChild(u);const a=document.createElement('div');a.className='bubble';a.textContent='Thinking…';log.appendChild(a);log.scrollTop=log.scrollHeight;const selected=document.getElementById('language')?.value||'English';const language=(selected.match(/\(([^)]+)\)/)?.[1]||selected.split(' (')[0]).trim();try{const r=await fetch('/api/assistant/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,language,context:{state:document.getElementById('regState')?.value||'',district:document.getElementById('regDistrict')?.value||'',village:document.getElementById('regVillage')?.value||''}})});if(!r.ok)throw Error('assistant unavailable');const data=await r.json();a.textContent=data.answer||reply(q);if(data.warning)a.title=data.warning;}catch(e){a.textContent=reply(q)+'\n\n(Offline fallback; connect the backend for language-specific responses.)'}log.scrollTop=log.scrollHeight}
document.getElementById('chatForm').addEventListener('submit',e=>{e.preventDefault();const i=document.getElementById('chatInput');if(i.value.trim())addChat(i.value.trim());i.value=''});
document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>{go('assistant');addChat(b.dataset.question)}));
document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value.toLowerCase();const match=[['soil','soil'],['moisture','soil'],['disease','disease'],['crop','disease'],['irrigation','irrigation'],['field','fields'],['report','reports'],['weather','weather'],['assistant','assistant'],['chat','assistant'],['setting','settings'],['dashboard','dashboard']].find(x=>q.includes(x[0]));if(match)go(match[1]);else{go('assistant');addChat(e.target.value)} }});
function attachPreview(inputId,previewId,resultId){document.getElementById(inputId).addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/')){toast('Please select an image file.');return}if(f.size>5*1024*1024){toast('Image must be smaller than 5 MB.');e.target.value='';return}const url=URL.createObjectURL(f);const p=document.getElementById(previewId);p.innerHTML='';const img=document.createElement('img');img.src=url;img.alt='Selected crop image preview';img.style.maxWidth='100%';img.style.maxHeight='220px';img.style.objectFit='contain';img.style.borderRadius='8px';p.appendChild(img);const r=document.getElementById(resultId);if(r){r.style.display='block';r.innerHTML='<b>Image selected: '+f.name.replace(/[<>&"]/g,'')+'</b><p>Image preview ready. A real disease prediction is not available until a validated image-classification model is connected.</p>'}})}
attachPreview('quickImage','quickPreview','quickResult');attachPreview('diseaseImage','diseasePreview','diseaseResult');
document.getElementById('scanBtn').addEventListener('click',async()=>{const f=document.getElementById('diseaseImage').files[0];const r=document.getElementById('diseaseResult');r.style.display='block';if(!f){r.innerHTML='<b>Please select an image first.</b><p>Choose a JPG, PNG or WEBP crop photo.</p>';return;}r.innerHTML='<b>Checking bundled crop-health reference records…</b><p>This checks reference information for the selected crop; it does not diagnose the pixels in the image.</p>';try{const crop=document.getElementById('diseaseCrop')?.value||'';const params=new URLSearchParams({crop,limit:'8'});const resp=await fetch('/api/crop-health?'+params.toString());if(!resp.ok)throw Error('Dataset unavailable');const data=await resp.json();r.innerHTML='<b>Image received — no AI diagnosis generated</b><p><b>Selected crop:</b> '+esc(crop)+'. The bundled dataset found '+data.count+' crop-health reference record(s). These are not inferred from the photo.</p>'+((data.records||[]).slice(0,5).map(x=>'<article class="panel" style="margin-top:8px"><h4>'+esc(x.Disease_or_Condition||'Crop-health condition')+'</h4><p><b>Symptoms:</b> '+esc(x.Typical_Symptoms||'Not listed')+'</p><p><b>Non-chemical management:</b> '+esc(x.Chemical_Free_or_Nonchemical_Management||'Consult local extension guidance')+'</p></article>').join('')||'<p>No crop-specific records found. Search the bundled dataset below using a symptom or condition.</p>')+'<p class="notice">'+esc(data.notice||'Reference data only; verify locally.')+'</p>';}catch(err){r.innerHTML='<b>Image preview ready; reference lookup failed.</b><p>Ensure the DHARTRIX backend is running. '+esc(err.message)+'</p>';}});
document.getElementById('estimateBtn').addEventListener('click',()=>{const measured=document.getElementById('measured').value,rain=+document.getElementById('rain').value,days=+document.getElementById('daysDry').value,soil=document.getElementById('soilType').value,crop=document.getElementById('soilCrop').value;const r=document.getElementById('soilResult');r.style.display='block';if(measured!==''&&(Number(measured)<0||Number(measured)>100)){r.innerHTML='<b>Invalid moisture value</b><p>Enter a value from 0 to 100.</p>';return}if(measured!==''){r.innerHTML='<b>Measured moisture entered: '+Number(measured).toFixed(1)+'%</b><p>This is a user-provided measurement, not independently verified. Whether it is suitable depends on crop, soil texture, sensor calibration and measurement depth.</p><p><b>Field context:</b> '+crop+' · '+soil+' soil · '+rain+' mm recent rainfall · '+days+' days since irrigation.</p>'}else{let note=rain>10?'Recent rainfall may have increased moisture; verify in the field.':days>4?'Several days since irrigation: check root-zone moisture before deciding.':'Use a calibrated measurement to establish current moisture.';r.innerHTML='<b>Field assessment prepared</b><p>'+note+'</p><p><b>Inputs:</b> '+crop+' · '+soil+' soil · '+rain+' mm rainfall · '+days+' days since irrigation.</p><p><b>No numeric prediction shown:</b> this prototype has no calibrated moisture model or live data connection, so inventing a percentage would be misleading.</p>'}});
document.getElementById('calcWater').addEventListener('click',()=>{const a=+document.getElementById('area').value,d=+document.getElementById('depth').value,e=+document.getElementById('efficiency').value,r=document.getElementById('waterResult');if(a<=0||d<0||e<=0||e>100){r.innerHTML='<b>Check inputs</b><p>Area must be above zero, depth cannot be negative, and efficiency must be 1–100%.</p>';return}const net=a*4046.8564224*d/1000, gross=net/(e/100);r.innerHTML='<b>Estimated gross water volume: '+Math.round(gross).toLocaleString()+' litres</b><p>Net field volume at the selected depth: '+Math.round(net).toLocaleString()+' litres.</p><p>Based on '+a+' acres, '+d+' mm water depth and '+e+'% application efficiency. This is a calculation scenario, not a recommendation to irrigate.</p>';});
