let fieldRecords=[];
function safeCell(v){return String(v??'—')}
function renderDashboardRecords(){
 const ids=['dashboardTable','fieldsTable'];
 ids.forEach((id,which)=>{const body=document.getElementById(id);if(!body)return;body.innerHTML='';if(!fieldRecords.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=which?9:11;td.className='empty';td.textContent='No field records yet. Add your first field in Farm Dashboard.';tr.appendChild(td);body.appendChild(tr);return;}
 fieldRecords.forEach((f,i)=>{const tr=document.createElement('tr');const vals=which?[f.village,f.state,f.district,f.coords,f.crop,f.manureDays+' days',f.temp+' °C',f.humidity+'%']:[f.village,f.state,f.district,f.coords,f.crop,f.manureDays+' days',f.temp+' °C',f.humidity+'%',f.soil,(f.source+(f.notes?' · '+f.notes:''))];vals.forEach(v=>{const td=document.createElement('td');td.textContent=safeCell(v);tr.appendChild(td)});const td=document.createElement('td');const b=document.createElement('button');b.className='link';b.textContent='Remove';b.onclick=()=>{fieldRecords.splice(i,1);renderDashboardRecords()};td.appendChild(b);tr.appendChild(td);body.appendChild(tr)});
 });
 document.getElementById('dashFieldCount').textContent=fieldRecords.length;document.getElementById('dashCropCount').textContent=new Set(fieldRecords.map(f=>f.crop)).size;
 const avg=(k)=>fieldRecords.length?(fieldRecords.reduce((s,f)=>s+Number(f[k]),0)/fieldRecords.length).toFixed(1):'—';document.getElementById('dashTempAvg').textContent=fieldRecords.length?avg('temp')+'°C':'—';document.getElementById('dashHumidityAvg').textContent=fieldRecords.length?avg('humidity')+'%':'—';
}
function renderFields(){renderDashboardRecords()}
function exportFieldRecords(){const rows=[['Village/locality','State/UT','District','GPS coordinates','Crop','Days since manure','Temperature C','Humidity percent','Soil type','Source','Notes'],...fieldRecords.map(f=>[f.village,f.state,f.district,f.coords,f.crop,f.manureDays,f.temp,f.humidity,f.soil,f.source,f.notes])];csvDownload('dhartrix-village-records.csv',rows)}
document.getElementById('exportCsv').onclick=exportFieldRecords;document.getElementById('fieldsExportCsv').onclick=exportFieldRecords;
document.getElementById('dashboardFieldForm').addEventListener('submit',e=>{e.preventDefault();const state=document.getElementById('dashState').value;const districtSelect=document.getElementById('dashDistrict');const district=(districtSelect.value||document.getElementById('dashDistrictManual').value).trim();const village=document.getElementById('dashVillage').value.trim();const tempRaw=document.getElementById('dashTemp').value,humidityRaw=document.getElementById('dashHumidity').value,manure=Number(document.getElementById('dashManureDays').value);if(!state||!district||!village){toast('Please select state, district and village/locality.');return}if(tempRaw===''||humidityRaw===''){toast('Fetch live weather or enter temperature and humidity before saving.');return}const temp=Number(tempRaw),humidity=Number(humidityRaw);if(temp < -10||temp>70||humidity<0||humidity>100||manure<0){toast('Please check manure days, temperature and humidity.');return}fieldRecords.push({village,state,district,coords:document.getElementById('gpsCoords').value||'Not provided',crop:document.getElementById('dashCrop').value,manureDays:manure,temp,humidity,soil:document.getElementById('dashSoil').value,source:document.getElementById('dashWeatherSource').value,notes:document.getElementById('dashNotes').value.trim()});renderDashboardRecords();e.target.reset();document.getElementById('dashDistrict').innerHTML='<option value="">Select state first</option>';document.getElementById('dashDistrictManual').style.display='none';document.getElementById('villageResults').innerHTML='';toast('Village and crop details saved in this browser session.');});
async function loadDistrictsForState(state){const select=document.getElementById('dashDistrict'),manual=document.getElementById('dashDistrictManual');select.innerHTML='<option value="">Loading districts…</option>';manual.style.display='none';try{if(!window.__indiaDistrictData){const resp=await fetch('https://raw.githubusercontent.com/CodingMation/indian-states-districts/main/data/india_states_districts.min.json');if(!resp.ok)throw new Error('dataset unavailable');window.__indiaDistrictData=await resp.json()}const data=window.__indiaDistrictData;let list=[];const norm=v=>String(v||'').toLowerCase().replace(/\s*\(ut\)/g,'').trim();const entries=Array.isArray(data)?data:(Array.isArray(data.states)?data.states:(Array.isArray(data.data)?data.data:[]));if(entries.length){const item=entries.find(x=>norm(x.name||x.state||x.state_name||x.stateName||x.name_en)===norm(state));if(item)list=item.districts||item.children||item.district_list||item.districtList||[]}else if(data&&typeof data==='object'){for(const [k,v] of Object.entries(data)){if(norm(k)===norm(state)){list=Array.isArray(v)?v:(v.districts||v.children||[]);break}}}list=list.map(x=>typeof x==='string'?x:(x.name||x.district||x.district_name||x.districtName||x.name_en||'')).filter(Boolean);if(!list.length)throw new Error('district list not found');manual.required=false;select.innerHTML='<option value="">Select district</option>'+list.sort((a,b)=>a.localeCompare(b)).map(x=>'<option>'+x.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))+'</option>').join('');}catch(err){select.innerHTML='<option value="">District list unavailable offline</option>';manual.style.display='block';manual.required=true;}}
document.getElementById('dashState').addEventListener('change',e=>{if(e.target.value)loadDistrictsForState(e.target.value);});


function csvDownload(filename,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download=filename;a.click();URL.revokeObjectURL(a.href)}
function exportFields(){csvDownload('dhartrix-field-report.csv',[['Field','Crop','Area (acres)','Soil','Location'],...fields.map(f=>[f.name,f.crop,f.area,f.soil,f.location])])}
document.getElementById('reportCsv').onclick=()=>exportFieldRecords();
