document.getElementById('language').addEventListener('change',e=>{try{applyLanguage()}catch{};toast('Language preference updated. Assistant replies use the selected language when live AI is configured.');});

// Live location and weather integration (OpenStreetMap Nominatim + Open-Meteo; no API key required).
let selectedCoords=null;
function setStatus(id,msg){const el=document.getElementById(id);if(el)el.textContent=msg}
async function reverseGeocode(lat,lon){const url=`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lon)}&zoom=16&addressdetails=1`;const r=await fetch(url,{headers:{'Accept-Language':'en'}});if(!r.ok)throw new Error('Reverse geocoding failed');return r.json()}
function addressParts(data){const a=data.address||{};return {state:a.state||a.region||'',district:a.state_district||a.district||a.county||'',village:a.village||a.hamlet||a.town||a.city||a.suburb||a.municipality||data.name||''}}
async function useGps(target='dashboard'){if(!navigator.geolocation){toast('GPS is not supported by this browser.');return}const status=target==='weather'?'weatherStatus':'gpsStatus';setStatus(status,'Requesting GPS permission…');navigator.geolocation.getCurrentPosition(async pos=>{const lat=pos.coords.latitude,lon=pos.coords.longitude;selectedCoords={lat,lon};const coord=`${lat.toFixed(6)}, ${lon.toFixed(6)}`;if(target==='weather'){document.getElementById('weatherCoords').value=coord;setStatus('weatherStatus','GPS captured. Loading live weather…')}else{document.getElementById('gpsCoords').value=coord;setStatus('gpsStatus','GPS location captured: '+coord+' · Finding village…')}try{const place=await reverseGeocode(lat,lon),parts=addressParts(place),display=parts.village||place.display_name||coord;if(target==='weather'){document.getElementById('weatherPlace').value=display;await loadLiveWeather(lat,lon,display)}else{if(parts.state){const st=document.getElementById('dashState');st.value=parts.state;if(st.value)await loadDistrictsForState(parts.state)}if(parts.district){const ds=document.getElementById('dashDistrict');const found=[...ds.options].find(o=>o.text.toLowerCase()===parts.district.toLowerCase());if(found)ds.value=found.value;else{const man=document.getElementById('dashDistrictManual');man.style.display='block';man.value=parts.district}}document.getElementById('dashVillage').value=display;document.getElementById('dashWeatherSource').value='Live weather API';await loadLiveWeather(lat,lon,display,'dashboard');setStatus('gpsStatus','GPS location: '+coord+' · Village: '+display)}}catch(err){if(target==='weather')await loadLiveWeather(lat,lon,coord);else{setStatus('gpsStatus','GPS captured ('+coord+'), but village lookup failed. Enter village/state/district manually.');await loadLiveWeather(lat,lon,coord,'dashboard')}}},err=>{setStatus(status,'Location unavailable: '+err.message+'. Allow location permission and use HTTPS or localhost.');toast('Could not access GPS location.')},{enableHighAccuracy:true,timeout:15000,maximumAge:60000})}
async function geocodeIndia(query){
  // Prefer same-origin backend proxy to avoid browser CORS/rate-limit failures.
  try { const r=await fetch(`/api/places?q=${encodeURIComponent(query)}`); if(r.ok){const rows=await r.json();if(Array.isArray(rows)&&rows.length)return rows.map(x=>({name:x.name||x.village||'',display_name:x.display_name||[x.name,x.village,x.district,x.state].filter(Boolean).join(', '),lat:x.latitude,lon:x.longitude,address:{village:x.village,district:x.district,state:x.state}}));} } catch(e) {}
  const url=`https://nominatim.openstreetmap.org/search?format=jsonv2&country=India&addressdetails=1&limit=6&q=${encodeURIComponent(query)}`;const r=await fetch(url,{headers:{'Accept-Language':'en'}});if(!r.ok)throw new Error('Place search unavailable');return r.json()
}
async function searchVillage(){const q=document.getElementById('dashVillage').value.trim();if(q.length<2){toast('Type a village or locality name first.');return}const box=document.getElementById('villageResults');box.innerHTML='Searching Indian locations…';try{const results=await geocodeIndia(q);box.innerHTML='';if(!results.length){box.textContent='No results found. Try village + district name.';return}results.forEach(item=>{const b=document.createElement('button');b.type='button';b.className='location-option';b.textContent=item.display_name;b.addEventListener('click',async()=>{const lat=Number(item.lat),lon=Number(item.lon),parts=addressParts(item);document.getElementById('dashVillage').value=parts.village||item.name||q;selectedCoords={lat,lon};document.getElementById('gpsCoords').value=`${lat.toFixed(6)}, ${lon.toFixed(6)}`;if(parts.state){document.getElementById('dashState').value=parts.state;await loadDistrictsForState(parts.state)}if(parts.district){const ds=document.getElementById('dashDistrict'),found=[...ds.options].find(o=>o.text.toLowerCase()===parts.district.toLowerCase());if(found)ds.value=found.value;else{const m=document.getElementById('dashDistrictManual');m.style.display='block';m.value=parts.district}}box.innerHTML='';await loadLiveWeather(lat,lon,document.getElementById('dashVillage').value,'dashboard');setStatus('gpsStatus','Location selected from map search: '+lat.toFixed(5)+', '+lon.toFixed(5))});box.appendChild(b)})}catch(e){box.textContent='Village search failed. Check your internet connection or use GPS.'}}
async function loadLiveWeather(lat,lon,label='Selected location',target='weather'){const statusId=target==='dashboard'?'gpsStatus':'weatherStatus';setStatus(statusId,'Fetching live weather and forecast…');try{const url=`https://api.open-meteo.com/v1/forecast?latitude=${encodeURIComponent(lat)}&longitude=${encodeURIComponent(lon)}&current=temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,rain,showers,weather_code,wind_speed_10m&hourly=temperature_2m,relative_humidity_2m,precipitation_probability&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum,wind_speed_10m_max,wind_gusts_10m_max&timezone=auto&forecast_days=15`;const resp=await fetch(url);if(!resp.ok)throw new Error('Weather provider returned an error');const d=await resp.json(),c=d.current;if(c&&typeof renderWeatherAlerts==='function')renderWeatherAlerts({current:c,daily:d.daily});if(!c)throw new Error('No current weather returned');if(target==='dashboard'){document.getElementById('dashTemp').value=Number(c.temperature_2m).toFixed(1);document.getElementById('dashHumidity').value=Number(c.relative_humidity_2m).toFixed(1);document.getElementById('dashWeatherSource').value='Live weather API';document.getElementById('homeWeatherTemp').textContent=`${c.temperature_2m}°C`;document.getElementById('homeWeatherHumidity').textContent=`Humidity ${c.relative_humidity_2m}% · Live`;document.getElementById('homeSoilTemp').textContent='Not measured by weather API';document.getElementById('homeAirHumidity').textContent=`${c.relative_humidity_2m}% · Live`;document.getElementById('homeForecastTemp').textContent=`${c.temperature_2m}°C`;document.getElementById('homeForecastPlace').textContent=label;document.getElementById('topLocation').textContent='📍 '+label;setStatus(statusId,`Live weather loaded for ${label}: ${c.temperature_2m}°C, ${c.relative_humidity_2m}% humidity.`)}else{document.getElementById('liveTemp').textContent=`${c.temperature_2m}°C`;document.getElementById('liveHumidity').textContent=`${c.relative_humidity_2m}%`;document.getElementById('liveWind').textContent=`${c.wind_speed_10m} km/h`;if(document.getElementById('liveRain'))document.getElementById('liveRain').textContent=`${c.precipitation} mm`;document.getElementById('weatherPlaceLabel').textContent=label;document.getElementById('topLocation').textContent='📍 '+label;document.getElementById('homeWeatherTemp').textContent=`${c.temperature_2m}°C`;document.getElementById('homeWeatherHumidity').textContent=`Humidity ${c.relative_humidity_2m}% · Live`;document.getElementById('homeAirHumidity').textContent=`${c.relative_humidity_2m}% · Live`;document.getElementById('homeForecastTemp').textContent=`${c.temperature_2m}°C`;document.getElementById('homeForecastPlace').textContent=label;setStatus(statusId,`Live data from Open-Meteo · Updated ${c.time.replace('T',' ')} · ${label}`);const forecast=document.getElementById('liveForecast');forecast.innerHTML='';d.daily.time.forEach((date,i)=>{const day=document.createElement('div');day.className='day';const dt=new Date(date+'T12:00:00');const icon=weatherEmoji(d.daily.weather_code[i]);day.innerHTML=`${dt.toLocaleDateString(undefined,{weekday:'short'})}<b>${icon}</b>${Math.round(d.daily.temperature_2m_max[i])}° / ${Math.round(d.daily.temperature_2m_min[i])}°<br><small>Rain chance ${d.daily.precipitation_probability_max?.[i]??'—'}% · ${d.daily.precipitation_sum?.[i]??'—'} mm</small><br><small>Wind ${d.daily.wind_speed_10m_max?.[i]??'—'} km/h · Gusts ${d.daily.wind_gusts_10m_max?.[i]??'—'} km/h</small>`;forecast.appendChild(day)});const mini=document.querySelector('.top-meta .weather-mini');if(mini)mini.innerHTML=`🌤️ <b>${c.temperature_2m}°C</b><br><small>Humidity ${c.relative_humidity_2m}%</small>`}return d}catch(err){setStatus(statusId,'Live weather could not load. Check internet access and try again. '+err.message);throw err}}
function weatherEmoji(code){if(code===0)return '☀️';if([1,2,3].includes(code))return '🌤️';if([45,48].includes(code))return '🌫️';if([51,53,55,56,57,61,63,65,66,67,80,81,82].includes(code))return '🌧️';if([71,73,75,77,85,86].includes(code))return '❄️';if([95,96,99].includes(code))return '⛈️';return '🌥️'}
