document.getElementById('weatherSearchBtn').addEventListener('click',async()=>{const q=document.getElementById('weatherPlace').value.trim();if(!q){toast('Enter an Indian village or town first.');return}setStatus('weatherStatus','Searching location…');try{const results=await geocodeIndia(q);if(!results.length)throw new Error('No matching place found');const r=results[0];selectedCoords={lat:Number(r.lat),lon:Number(r.lon)};document.getElementById('weatherCoords').value=`${Number(r.lat).toFixed(6)}, ${Number(r.lon).toFixed(6)}`;await loadLiveWeather(Number(r.lat),Number(r.lon),r.display_name)}catch(e){setStatus('weatherStatus','Place search failed: '+e.message)}});
document.getElementById('dashVillage').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchVillage()}});



// DHARTRIX backend integration helpers.
// Use these helpers from the UI when you want server-backed weather and location search.
const DHARTRIX_API = "/api";

async function dhartrixFetchWeather(latitude, longitude) {
  const response = await fetch(`${DHARTRIX_API}/weather?latitude=${encodeURIComponent(latitude)}&longitude=${encodeURIComponent(longitude)}`);
  if (!response.ok) throw new Error("Weather service unavailable");
  return response.json();
}

async function dhartrixSearchPlaces(query) {
  const response = await fetch(`${DHARTRIX_API}/places?q=${encodeURIComponent(query)}`);
  if (!response.ok) throw new Error("Place search unavailable");
  return response.json();
}


// QpiAI integrations are backend-only; never put API keys in frontend JavaScript.
const qpiDemoServices = [
  {service_id:'LAB01',service_name:'Demo Soil Testing Lab',test_type:'soil_test',cost_inr:500,turnaround_hours:24,available:true},
  {service_id:'LAB02',service_name:'Demo Plant Diagnostic Lab',test_type:'plant_test',cost_inr:800,turnaround_hours:48,available:true},
  {service_id:'AGR01',service_name:'Demo Agronomist Consultation',test_type:'expert_visit',cost_inr:300,turnaround_hours:12,available:true},
  {service_id:'LAB03',service_name:'Demo Specialist Lab',test_type:'specialist_test',cost_inr:1000,turnaround_hours:36,available:true}
];
async function qpiRequest(path, options={}) {
  const response = await fetch(`/api${path}`, {headers:{'Content-Type':'application/json',...(options.headers||{})},...options});
  let data; try { data=await response.json(); } catch { data={detail:'Unexpected response'}; }
  if(!response.ok) throw new Error(data.detail || data.message || `HTTP ${response.status}`);
  return data;
}
function prettyQpi(id,data){const el=document.getElementById(id);if(el)el.textContent=JSON.stringify(data,null,2)}
async function refreshQpiOptStatus(){const el=document.getElementById('optStatus');el.textContent='Checking…';try{const d=await qpiRequest('/qpiai/opt/status');el.textContent=d.message+(d.remote_execution_verified?' Remote execution verified.':'');}catch(e){el.textContent='Opt status unavailable: '+e.message}}
async function refreshQpiCloudStatus(){const el=document.getElementById('cloudStatus');el.textContent='Checking…';try{const d=await qpiRequest('/qpiai/cloud/status');el.textContent=d.message;}catch(e){el.textContent='QCloud status unavailable: '+e.message}}
const optRefresh=document.getElementById('refreshOptStatus'); if(optRefresh)optRefresh.addEventListener('click',refreshQpiOptStatus);
const cloudRefresh=document.getElementById('refreshCloudStatus'); if(cloudRefresh)cloudRefresh.addEventListener('click',refreshQpiCloudStatus);
const quboBtn=document.getElementById('buildQuboBtn'); if(quboBtn)quboBtn.addEventListener('click',async()=>{const budget=Number(document.getElementById('optBudget').value);if(!Number.isFinite(budget)||budget<0){toast('Enter a valid non-negative budget.');return}const out=document.getElementById('quboResult');out.textContent='Building QUBO…';try{const d=await qpiRequest('/qpiai/opt/qubo',{method:'POST',body:JSON.stringify({budget_inr:budget,services:qpiDemoServices})});prettyQpi('quboResult',d);}catch(e){out.textContent='Could not build model: '+e.message}});
const optSubmit=document.getElementById('submitOptBtn');if(optSubmit)optSubmit.addEventListener('click',async()=>{const el=document.getElementById('optSubmitResult');el.textContent='Contacting backend…';try{const d=await qpiRequest('/qpiai/opt/submit',{method:'POST',body:'{}'});el.textContent=d.message+'\n'+JSON.stringify(d.response||{},null,2);}catch(e){el.textContent='Opt submission failed: '+e.message}});
const cloudRun=document.getElementById('runCloudBtn');if(cloudRun)cloudRun.addEventListener('click',async()=>{if(!confirm('This will contact QpiAI Quantum Cloud and may consume account credits. Continue?'))return;const out=document.getElementById('cloudResult');out.textContent='Submitting explicit QCloud smoke test…';cloudRun.disabled=true;try{const shots=Number(document.getElementById('cloudShots').value);const d=await qpiRequest(`/qpiai/cloud/smoke-test?shots=${shots}`,{method:'POST',body:'{}'});prettyQpi('cloudResult',d);}catch(e){out.textContent='QCloud test failed: '+e.message;}finally{cloudRun.disabled=false;refreshQpiCloudStatus()}});
refreshQpiOptStatus();refreshQpiCloudStatus();

/* DHARTRIX extended features: local demo data + server-side accounts/AI. */
function currentLangName(){const v=document.getElementById('language')?.value||'English';return (v.match(/\(([^)]+)\)/)?.[1]||v).trim()}
const DHARTRIX_STORE={token:'dhartrix_token',profile:'dhartrix_profile',nutrients:'dhartrix_nutrients',bookings:'dhartrix_bookings',practices:'dhartrix_practices',settings:'dhartrix_settings'};
const readStore=(k,fb=[])=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(fb))}catch{return fb}};
const writeStore=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const apiJson=async(path,options={})=>{const headers={'Content-Type':'application/json',...(options.headers||{})};const token=localStorage.getItem(DHARTRIX_STORE.token);if(token)headers.Authorization='Bearer '+token;const r=await fetch(path,{...options,headers});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.detail||d.message||('Request failed: '+r.status));return d};
const authGate=document.getElementById('authGate'), mainApp=document.getElementById('mainApp'), authMessage=document.getElementById('authMessage');
function showAuth(mode='login'){for(const id of ['loginForm','registerForm','forgotPasswordForm','resetPasswordForm']){const el=document.getElementById(id);if(el)el.hidden=id!==({login:'loginForm',register:'registerForm',forgot:'forgotPasswordForm',reset:'resetPasswordForm'}[mode]||'loginForm');}document.getElementById('authTitle').textContent=mode==='register'?'Create your farmer profile':mode==='forgot'?'Request password reset':mode==='reset'?'Choose a new password':'Welcome to DHARTRIX';document.getElementById('authSubtitle').textContent=mode==='register'?'Tell us your farming area and preferred language.':mode==='forgot'?'Request a one-time reset code.':mode==='reset'?'Reset codes expire after 10 minutes.':'Sign in with your email or mobile number.';document.getElementById('showLogin').classList.toggle('primary',mode==='login');document.getElementById('showRegister').classList.toggle('primary',mode==='register');authMessage.textContent='';}
document.getElementById('showLogin').addEventListener('click',()=>showAuth('login'));document.getElementById('showRegister').addEventListener('click',()=>showAuth('register'));
document.getElementById('showForgotPassword').addEventListener('click',()=>{document.getElementById('forgotIdentifier').value=document.getElementById('loginIdentifier').value;showAuth('forgot')});
document.getElementById('backToLogin1').addEventListener('click',()=>showAuth('login'));document.getElementById('backToLogin2').addEventListener('click',()=>showAuth('login'));
const stateSelect=document.getElementById('regState');if(stateSelect){stateSelect.innerHTML='<option value="">Select state / UT</option>'+indianStates.map(s=>`<option>${s}</option>`).join('');}
function openApp(profile){authGate.style.display='none';mainApp.hidden=false;document.getElementById('signedInName').textContent='👨🏽‍🌾 '+(profile.name||'Farmer');if(profile.language){const language=document.getElementById('language');if(language){const opt=[...language.options].find(o=>o.textContent.toLowerCase().includes(profile.language.toLowerCase()));if(opt)language.value=opt.value;}}go('dashboard');applyLanguage();}
document.getElementById('loginForm').addEventListener('submit',async e=>{e.preventDefault();authMessage.textContent='Signing in…';try{const d=await apiJson('/api/auth/login',{method:'POST',body:JSON.stringify({identifier:document.getElementById('loginIdentifier').value,password:document.getElementById('loginPassword').value})});localStorage.setItem(DHARTRIX_STORE.token,d.token);writeStore(DHARTRIX_STORE.profile,d.farmer);openApp(d.farmer)}catch(err){authMessage.textContent=err.message}});
document.getElementById('forgotPasswordForm').addEventListener('submit',async e=>{e.preventDefault();const identifier=document.getElementById('forgotIdentifier').value.trim();authMessage.textContent='Requesting reset code…';try{const d=await apiJson('/api/auth/forgot-password',{method:'POST',body:JSON.stringify({identifier})});document.getElementById('resetIdentifier').value=identifier;showAuth('reset');authMessage.textContent=d.message}catch(err){authMessage.textContent=err.message}});
document.getElementById('resetPasswordForm').addEventListener('submit',async e=>{e.preventDefault();authMessage.textContent='Resetting password…';try{const d=await apiJson('/api/auth/reset-password',{method:'POST',body:JSON.stringify({identifier:document.getElementById('resetIdentifier').value.trim(),code:document.getElementById('resetCode').value.trim(),new_password:document.getElementById('resetNewPassword').value})});showAuth('login');authMessage.textContent=d.message;document.getElementById('loginIdentifier').value=document.getElementById('resetIdentifier').value;document.getElementById('loginPassword').value=''}catch(err){authMessage.textContent=err.message}});
document.getElementById('registerForm').addEventListener('submit',async e=>{e.preventDefault();authMessage.textContent='Creating account…';const payload={name:document.getElementById('regName').value,email:document.getElementById('regEmail').value,password:document.getElementById('regPassword').value,phone:document.getElementById('regPhone').value,state:document.getElementById('regState').value,district:document.getElementById('regDistrict').value,village:document.getElementById('regVillage').value,language:document.getElementById('regLanguage').value,farming_level:document.getElementById('regLevel').value,subscription_interest:document.getElementById('regSubscription').value};try{const d=await apiJson('/api/auth/register',{method:'POST',body:JSON.stringify(payload)});localStorage.setItem(DHARTRIX_STORE.token,d.token);writeStore(DHARTRIX_STORE.profile,d.farmer);if(payload.subscription_interest==='interest')toast('Profile saved. You can request sensor installation from Sensor Installation.');openApp(d.farmer)}catch(err){authMessage.textContent=err.message}});
document.getElementById('logoutBtn').addEventListener('click',async()=>{try{await apiJson('/api/auth/logout',{method:'POST',body:'{}'})}catch{}localStorage.removeItem(DHARTRIX_STORE.token);localStorage.removeItem(DHARTRIX_STORE.profile);mainApp.hidden=true;authGate.style.display='grid';showAuth('login')});
(async()=>{const token=localStorage.getItem(DHARTRIX_STORE.token);if(!token){showAuth('login');return}try{const d=await apiJson('/api/auth/me');writeStore(DHARTRIX_STORE.profile,d.farmer);openApp(d.farmer)}catch{localStorage.removeItem(DHARTRIX_STORE.token);showAuth('login')}})();

