// Soil test and previous nutrient/fertilizer/pesticide input history.
const nutrientRows=readStore(DHARTRIX_STORE.nutrients,[]);
function renderNutrients(){const el=document.getElementById('nutRecords');if(!el)return;if(!nutrientRows.length){el.innerHTML='<p class="empty">No soil-test or input records saved yet.</p>';return}const cols=['field','date','ph','n','p','k','category','product','quantity','applied','notes'];el.innerHTML='<div class="table-wrap"><table class="table"><thead><tr>'+['Field','Test date','pH','N','P','K','Input category','Input used','Quantity','Applied','Notes'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+nutrientRows.map(r=>'<tr>'+cols.map(c=>'<td>'+escapeHtml(r[c]||'—')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
document.getElementById('nutrientForm').addEventListener('submit',e=>{e.preventDefault();nutrientRows.push({field:nutField.value,date:nutDate.value,ph:nutPH.value,n:nutN.value,p:nutP.value,k:nutK.value,category:nutCategory.value,product:nutProduct.value,quantity:nutQty.value,applied:nutApplied.value,notes:nutNotes.value});writeStore(DHARTRIX_STORE.nutrients,nutrientRows);renderNutrients();e.target.reset();toast('Soil test and input history saved in this browser.')});
function downloadCSV(filename,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href)}
document.getElementById('nutExport').addEventListener('click',()=>downloadCSV('dhartrix-soil-input-history.csv',[['field','date','ph','nitrogen','phosphorus','potassium','input_category','input','quantity','application_date','notes'],...nutrientRows.map(r=>[r.field,r.date,r.ph,r.n,r.p,r.k,r.category,r.product,r.quantity,r.applied,r.notes])]));renderNutrients();

// Beginner-friendly organic guidance: general practices only; crop-specific rates require local extension advice.
document.getElementById('organicForm').addEventListener('submit',e=>{e.preventDefault();const crop=document.getElementById('organicCrop').value,goal=document.getElementById('organicGoal').value,level=document.getElementById('organicLevel').value,soil=document.getElementById('organicSoil').value,context=document.getElementById('organicContext').value;const steps={soil:['Collect a representative soil sample and request a lab test for pH and available nutrients.','Record crop history and every input used in the last season.','Add mature compost or locally approved organic amendments based on soil-test guidance.','Use crop residue mulch where appropriate; keep the stem collar clear and avoid contaminated residues.','Consider crop rotation and cover/green-manure crops suited to your climate and water availability.','Re-test soil and compare crop response over time.'],pest:['Inspect several plants across the field and record the pest, crop stage and damage level.','Identify the pest before treating; use a local agricultural extension service if uncertain.','Use field sanitation, crop rotation, netting or physical removal when suitable.','Conserve beneficial insects and consider traps or biological controls only when suitable for the identified pest.','If a product is needed, use only locally registered products exactly as labelled; do not mix unknown products.'],disease:['Photograph both sides of affected leaves and unaffected plants; note how quickly symptoms spread.','Avoid handling healthy plants after suspect infected plants; clean tools and avoid moving potentially infected material.','Improve spacing and drainage if excess leaf wetness or waterlogging is present and crop guidance supports it.','Remove infected residues only when recommended for the suspected disease; dispose of them safely.','Confirm the disease with a qualified extension worker or diagnostic lab before treatment.'],nutrition:['Use a soil test and, if available, plant tissue analysis before adding nutrients.','Check pH, root health, irrigation and recent weather because symptoms can mimic nutrient deficiency.','Use mature compost or approved organic nutrient sources in locally recommended quantities.','Record source, quantity, date and crop response; avoid stacking multiple nutrient products without guidance.'],water:['Measure soil moisture at the active root depth at several field locations.','Use mulch, repair leaks and schedule irrigation around crop stage and forecast rainfall.','Consider drip or other efficient irrigation where technically and economically suitable.','Do not infer groundwater depth from surface soil moisture; obtain hydrogeological advice for borewell decisions.'],transition:['Start with soil testing and document current yields, input costs and pest pressure.','Trial organic practices on a small area before whole-farm conversion.','Plan rotations, cover crops, compost supply and integrated pest management together.','Verify local organic certification rules and permitted inputs before making a certification claim.','Track yield, labour, input costs and soil indicators over multiple seasons.']};let html='<b>'+escapeHtml(crop)+' · '+escapeHtml(goal)+' · '+escapeHtml(level)+'</b><p>Soil entered: '+escapeHtml(soil)+'. Context: '+escapeHtml(context||'not supplied')+'</p><ol>'+steps[goal].map(x=>'<li>'+escapeHtml(x)+'</li>').join('')+'</ol><div class="notice">These are general educational practices, not a confirmed diagnosis or crop-specific application rate. Check local extension recommendations, harvest intervals and product labels.</div>';document.getElementById('organicResult').innerHTML=html});

// Sensor installation request. This records a request locally; it does not create a paid/confirmed booking.
const bookingRows=readStore(DHARTRIX_STORE.bookings,[]);document.getElementById('sensorBookingForm').addEventListener('submit',e=>{e.preventDefault();const b={name:bookName.value,phone:bookPhone.value,state:bookState.value,location:bookLocation.value,area:bookArea.value,sensor:bookSensor.value,plan:bookPlan.value,time:bookTime.value,notes:bookNotes.value,createdAt:new Date().toISOString(),status:'Request saved locally — not confirmed'};bookingRows.push(b);writeStore(DHARTRIX_STORE.bookings,bookingRows);document.getElementById('bookingResult').textContent='Request saved in this browser. Status: not confirmed. No payment was taken. Contact a verified local installer to confirm availability and price.';toast('Installation request saved; no payment taken.')});

// Farmer-to-farmer knowledge posts with optional browser speech recognition.
const practices=readStore(DHARTRIX_STORE.practices,[]);function renderPractices(){const el=document.getElementById('practiceList');if(!el)return;el.innerHTML=practices.length?'<h3>Saved practices</h3>'+practices.slice().reverse().map(p=>'<article class="panel" style="margin-top:8px"><b>'+escapeHtml(p.title)+'</b><p>'+escapeHtml(p.crop||'General')+'</p><p>'+escapeHtml(p.text)+'</p><small>'+escapeHtml(p.safety||'No safety note supplied')+' · '+escapeHtml(p.date)+'</small></article>').join(''):'<p class="empty">No community practices added yet.</p>'}
document.getElementById('practiceForm').addEventListener('submit',async e=>{e.preventDefault();const profile=(()=>{try{return JSON.parse(localStorage.getItem('dhartrix_farmer_profile')||'{}')}catch{return {}}})();const payload={title:practiceTitle.value.trim(),crop:practiceCrop.value.trim(),text:practiceText.value.trim(),safety:practiceSafety.value.trim(),state:profile.state||'',district:profile.district||'',village:profile.village||'',author_label:profile.name||'Farmer'};try{const response=await fetch('/api/farmer-practices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error('Shared database is unavailable');const result=await response.json();practices.push({...payload,date:new Date().toLocaleString(),shared:true,id:result.record.id});writeStore(DHARTRIX_STORE.practices,practices);renderPractices();e.target.reset();toast('Practice shared to the DHARTRIX backend.')}catch(err){practices.push({...payload,date:new Date().toLocaleString(),shared:false});writeStore(DHARTRIX_STORE.practices,practices);renderPractices();toast('Saved on this browser only; backend sharing failed.')}});renderPractices();
document.getElementById('practiceVoice').addEventListener('click',()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){practiceVoiceStatus.textContent='Speech recognition is not supported in this browser. Type the practice instead.';return}const rec=new SR();rec.lang=({Hindi:'hi-IN',Kannada:'kn-IN',Telugu:'te-IN',Tamil:'ta-IN',Malayalam:'ml-IN',Bengali:'bn-IN',Marathi:'mr-IN'}[document.getElementById('language').value]||'en-IN');rec.interimResults=false;practiceVoiceStatus.textContent='Listening…';rec.onresult=e=>{practiceText.value+=(practiceText.value?' ':'')+e.results[0][0].transcript;practiceVoiceStatus.textContent='Voice captured. Please review the transcription before saving.'};rec.onerror=()=>practiceVoiceStatus.textContent='Could not capture speech. Check microphone permission or type the practice.';rec.onend=()=>{if(practiceVoiceStatus.textContent==='Listening…')practiceVoiceStatus.textContent='No speech captured.'};rec.start()});

// Weather risk alerts from forecast data. These are heuristic advisories, not official cyclone warnings.
function renderWeatherAlerts(data){const alerts=[];const c=data.current||{},d=data.daily||{};if(Number(c.wind_speed_10m)>=40)alerts.push('Strong wind advisory: current forecast-grid wind is '+c.wind_speed_10m+' km/h. Secure loose materials and check official warnings.');if(Number(c.precipitation)>=20)alerts.push('Heavy precipitation currently reported by the weather model. Check drainage and official local alerts.');const probs=d.precipitation_probability_max||[];if(probs.some(x=>Number(x)>=70))alerts.push('High rain probability in the forecast. Review drainage, field access and irrigation plans.');if(Number(c.temperature_2m)>=38)alerts.push('High temperature advisory: protect workers, check crop water stress and follow local heat guidance.');const el=document.getElementById('weatherStatus');if(alerts.length){el.innerHTML='<b>Weather watch</b><ul>'+alerts.map(a=>'<li>'+escapeHtml(a)+'</li>').join('')+'</ul><p>Forecast-based advisory only. Cyclone and emergency warnings must come from IMD and local authorities.</p>'}else if(el)el.textContent='Live data received. No configured prototype threshold was triggered; continue to follow official local alerts.';}
// Wrap existing weather display callback when API returns, by observing fetch response for /api/weather.
const originalFetch=window.fetch.bind(window);window.fetch=async(...args)=>{const res=await originalFetch(...args);try{const url=String(args[0]);if(url.includes('/api/weather')&&res.ok){const clone=res.clone();clone.json().then(renderWeatherAlerts).catch(()=>{})}}catch{}return res};

// Assistant now calls a server-side AI API when OPENAI_API_KEY is configured; otherwise the backend clearly labels fallback mode.
async function sendAssistantMessage(q){const log=document.getElementById('mainChat');const u=document.createElement('div');u.className='bubble user';u.textContent=q;log.appendChild(u);const a=document.createElement('div');a.className='bubble';a.textContent='Checking guidance…';log.appendChild(a);log.scrollTop=log.scrollHeight;try{const profile=readStore(DHARTRIX_STORE.profile,{});const d=await apiJson('/api/assistant/chat',{method:'POST',body:JSON.stringify({message:q,language:document.getElementById('language').value||profile.language||'English',context:{state:profile.state,district:profile.district,village:profile.village,farming_level:profile.farming_level}})});a.textContent=(d.mode==='live_ai'?'AI assistant · '+d.model+': ':'Guidance fallback: ')+d.answer+(d.warning?'\n\n'+d.warning:'');if(document.getElementById('voiceReplies')?.checked&&'speechSynthesis'in window){speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(d.answer);const lang=document.getElementById('language').value;utter.lang=({'Hindi':'hi-IN','Kannada':'kn-IN','Telugu':'te-IN','Tamil':'ta-IN','Malayalam':'ml-IN','Bengali':'bn-IN','Marathi':'mr-IN'}[currentLangName()]||'en-IN');speechSynthesis.speak(utter)}}catch(err){a.textContent='Assistant unavailable: '+err.message+' Please try again or consult local agricultural extension guidance.'}log.scrollTop=log.scrollHeight}
function addChat(q){sendAssistantMessage(q)}
const chatForm=document.getElementById('chatForm');if(chatForm){chatForm.addEventListener('submit',e=>{e.preventDefault();const i=document.getElementById('chatInput');const q=i.value.trim();if(q)sendAssistantMessage(q);i.value=''})}
// Add voice input/output controls to assistant UI.
const chatFormEl=document.getElementById('chatForm');if(chatFormEl&&!document.getElementById('assistantVoiceControls')){const controls=document.createElement('div');controls.id='assistantVoiceControls';controls.className='check-row';controls.innerHTML='<label><input type="checkbox" id="voiceReplies" checked> Speak assistant replies</label><button type="button" class="btn" id="assistantMic">🎙️ Ask by voice</button><small id="assistantVoiceStatus" class="fineprint"></small>';chatFormEl.parentNode.insertBefore(controls,chatFormEl.nextSibling);document.getElementById('assistantMic').addEventListener('click',()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;const st=document.getElementById('assistantVoiceStatus');if(!SR){st.textContent='Voice input is not supported in this browser; type your question.';return}const rec=new SR();rec.lang=({'Hindi':'hi-IN','Kannada':'kn-IN','Telugu':'te-IN','Tamil':'ta-IN','Malayalam':'ml-IN','Bengali':'bn-IN','Marathi':'mr-IN'}[currentLangName()]||'en-IN');rec.onstart=()=>st.textContent='Listening…';rec.onresult=e=>{document.getElementById('chatInput').value=e.results[0][0].transcript;st.textContent='Speech captured. Press send to ask.'};rec.onerror=()=>st.textContent='Microphone unavailable; type your question.';rec.start()})}

