function applyLanguage(){
 const sel=document.getElementById('language');const raw=sel?.value||'English';const lang=(raw.match(/\(([^)]+)\)/)?.[1]||raw.split(' (')[0]).trim();const dict=uiTranslations[lang]||{};
 try{localStorage.setItem('dhartrix_ui_language',sel.value)}catch{}
 // Translate the navigation while preserving its icons and original English labels.
 document.querySelectorAll('[data-page]').forEach(b=>{const icon=b.querySelector('.ico');if(!b.dataset.originalLabel){const clone=b.cloneNode(true);clone.querySelector('.ico')?.remove();b.dataset.originalLabel=clone.textContent.trim()}const label=b.dataset.originalLabel;if(icon)b.innerHTML=icon.outerHTML+(dict[label]||label);else b.textContent=dict[label]||label;});
 // Translate exact, short leaf text without altering form values or dynamic data.
 const candidates=document.querySelectorAll('h1,h2,h3,h4,p,label,button,a,small,strong,span,option,summary');
 candidates.forEach(el=>{if(el.closest('[data-page]'))return;if(el.children.length>0)return;const original=el.dataset.i18nOriginal??el.textContent.trim();if(!el.dataset.i18nOriginal)el.dataset.i18nOriginal=original;if(!original)return;const translated=dict[original];if(translated!==undefined)el.textContent=translated;else if(lang==='English')el.textContent=original;});
 // Translate placeholders and accessible labels; preserve original for switching languages.
 document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{const o=el.dataset.i18nPlaceholder??el.placeholder;if(!el.dataset.i18nPlaceholder)el.dataset.i18nPlaceholder=o;if(dict[o]!==undefined)el.placeholder=dict[o];else if(lang==='English')el.placeholder=o;});
 document.querySelectorAll('[title]').forEach(el=>{const o=el.dataset.i18nTitle??el.title;if(!el.dataset.i18nTitle)el.dataset.i18nTitle=o;if(dict[o]!==undefined)el.title=dict[o];else if(lang==='English')el.title=o;});
 const title=document.getElementById('authTitle');if(title){if(!title.dataset.i18nOriginal)title.dataset.i18nOriginal='Welcome to DHARTRIX';title.textContent=dict['Welcome to DHARTRIX']||title.dataset.i18nOriginal;}
 const dir=lang==='Urdu'?'rtl':'ltr';document.documentElement.dir=dir;
}
document.getElementById('language').addEventListener('change',()=>{applyLanguage();const setting=document.getElementById('settingsLanguage');if(setting)setting.value=document.getElementById('language').value.split(' (')[0];const reg=document.getElementById('regLanguage');if(reg){const name=(document.getElementById('language').value.match(/\(([^)]+)\)/)?.[1]||document.getElementById('language').value).trim();const opt=[...reg.options].find(o=>o.textContent.toLowerCase()===name.toLowerCase());if(opt)reg.value=opt.value;} });
const settingsForm=document.getElementById('settingsForm');settingsForm.addEventListener('submit',e=>{e.preventDefault();const s={farmName:farmName.value,language:settingsLanguage.value,units:settingsUnits.value,email:alertEmail.value,phone:alertPhone.value,severity:alertSeverity.value,channels:{inApp:alertInApp.checked,email:alertMail.checked,sms:alertSms.checked,whatsapp:alertWhatsapp.checked}};writeStore(DHARTRIX_STORE.settings,s);const langSelect=document.getElementById('language');const langOpt=[...langSelect.options].find(o=>o.textContent.toLowerCase()===s.language.toLowerCase()||o.textContent.toLowerCase().includes('('+s.language.toLowerCase()+')'));if(langOpt)langSelect.value=langOpt.value;applyLanguage();settingsStatus.textContent='Preferences saved locally. Email/SMS/WhatsApp are not sent until a notification provider is configured.';toast('Settings saved locally.')});
// Do not auto-apply a previously saved language on page startup. The login screen stays English.
const savedSettings=readStore(DHARTRIX_STORE.settings,null);if(savedSettings){farmName.value=savedSettings.farmName||'My Farm';settingsLanguage.value=savedSettings.language||'English';alertEmail.value=savedSettings.email||'';alertPhone.value=savedSettings.phone||'';if(savedSettings.channels){alertInApp.checked=!!savedSettings.channels.inApp;alertMail.checked=!!savedSettings.channels.email;alertSms.checked=!!savedSettings.channels.sms;alertWhatsapp.checked=!!savedSettings.channels.whatsapp}}

// CSV disease reference search. This is structured-data lookup, not image inference.
// Store and display real, manually entered sensor points by field zone/depth.
const sensorRows=readStore('dhartrix_sensor_points',[]);
function renderSensorPoints(){const table=document.getElementById('sensorReadingTable'),summary=document.getElementById('sensorMapSummary');if(!table||!summary)return;if(!sensorRows.length){summary.textContent='No sensor readings saved.';table.innerHTML='';return}const latest=sensorRows.slice(-100);const zones=new Map();latest.forEach(r=>{const key=r.field+' · '+r.zone;if(!zones.has(key))zones.set(key,[]);zones.get(key).push(r)});summary.innerHTML='<b>Measured zones (not interpolated):</b><div class="field-map" style="margin-top:10px">'+[...zones.entries()].map(([name,rows])=>{const avg=rows.reduce((s,r)=>s+r.moisture,0)/rows.length;const band=avg<20?'LOW — verify crop/soil threshold':avg<40?'Recorded moisture: '+avg.toFixed(1)+'%':'Higher reading: '+avg.toFixed(1)+'%';return '<div class="field-tile"><b>'+escapeHtml(name)+'</b><span>'+band+'</span><span>'+rows.length+' measurement(s)</span></div>'}).join('')+'</div><p class="fineprint">Color-free summary based only on logged points. Moisture thresholds are not universal and the app does not estimate unsampled zones.</p>';table.innerHTML='<table class="table"><thead><tr><th>Timestamp</th><th>Field</th><th>Zone</th><th>Depth</th><th>Moisture</th><th>Soil temp</th><th>Borewell level</th></tr></thead><tbody>'+latest.slice().reverse().map(r=>'<tr>'+[r.time,r.field,r.zone,r.depth+' cm',r.moisture+'%',r.soilTemp===''?'—':r.soilTemp+' °C',r.waterLevel===''?'—':r.waterLevel+' m'].map(v=>'<td>'+escapeHtml(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
document.getElementById('sensorReadingsForm').addEventListener('submit',e=>{e.preventDefault();const row={field:sensorField.value.trim(),zone:sensorZone.value.trim(),depth:Number(sensorDepth.value),moisture:Number(sensorMoisture.value),soilTemp:sensorSoilTemp.value,waterLevel:sensorWaterLevel.value,time:new Date().toLocaleString()};if(!Number.isFinite(row.depth)||row.depth<=0||!Number.isFinite(row.moisture)||row.moisture<0||row.moisture>100){toast('Check depth and moisture values.');return}sensorRows.push(row);writeStore('dhartrix_sensor_points',sensorRows);renderSensorPoints();e.target.reset();toast('Sensor point saved locally.')});renderSensorPoints();

// DHARTRIX enhancement layer: bundled dataset search, farmer profile, recommendations and theme.
(function(){
  const $=id=>document.getElementById(id);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const savedProfile=()=>{try{return JSON.parse(localStorage.getItem('dhartrix_farmer_profile')||'{}')}catch{return {}}};
  function fillProfile(){const p=savedProfile();Object.entries({profileName:'name',profileAge:'age',profilePhone:'phone',profileLanguage:'language',profileState:'state',profileDistrict:'district',profileVillage:'village',profileFarmArea:'farm_area',profileCrops:'crops',profileExperience:'experience',profileNotes:'notes'}).forEach(([id,k])=>{if($(id)&&p[k]!=null)$(id).value=p[k]});}
  $('farmerProfileForm')?.addEventListener('submit',e=>{e.preventDefault();const p={};Object.entries({profileName:'name',profileAge:'age',profilePhone:'phone',profileLanguage:'language',profileState:'state',profileDistrict:'district',profileVillage:'village',profileFarmArea:'farm_area',profileCrops:'crops',profileExperience:'experience',profileNotes:'notes'}).forEach(([id,k])=>p[k]=$(id)?.value||'');localStorage.setItem('dhartrix_farmer_profile',JSON.stringify(p));if($('profileStatus'))$('profileStatus').textContent='Profile saved on this device.';if($('language')&&p.language){$('language').value=p.language;try{applyLanguage()}catch{}}});fillProfile();
  const applyTheme=v=>{document.documentElement.dataset.theme=v;document.body.classList.toggle('dark-theme',v==='dark');localStorage.setItem('dhartrix_theme',v)};
  const theme=localStorage.getItem('dhartrix_theme')||'light';if($('themeChoice'))$('themeChoice').value=theme;applyTheme(theme);$('themeChoice')?.addEventListener('change',e=>applyTheme(e.target.value));
  if($('settingsForm'))$('settingsForm').addEventListener('submit',()=>{if($('settingsLanguage')&&$('language')){$('language').value=$('settingsLanguage').value;try{applyLanguage()}catch{}}});
  $('cropDatasetForm')?.addEventListener('submit',async e=>{e.preventDefault();const out=$('datasetResults');out.textContent='Searching bundled crop-health records…';const params=new URLSearchParams();if($('datasetCrop').value.trim())params.set('crop',$('datasetCrop').value.trim());if($('datasetQuery').value.trim())params.set('q',$('datasetQuery').value.trim());try{const r=await fetch('/api/crop-health?'+params.toString());if(!r.ok)throw new Error('Dataset search returned '+r.status);const d=await r.json();if(!d.records.length){out.innerHTML='<b>No matching reference records found.</b><p>Try a broader crop name, symptom or disease term.</p>';return}out.innerHTML='<b>'+d.count+' matching reference record(s)</b>'+d.records.map(x=>'<article class="panel" style="margin-top:10px"><h3>'+esc(x.Crop)+' — '+esc(x.Disease_or_Condition)+'</h3><p><b>Type:</b> '+esc(x.Condition_Type)+' · <b>Cause/association:</b> '+esc(x.Cause_or_Association)+'</p><p><b>Typical symptoms:</b> '+esc(x.Typical_Symptoms)+'</p><p><b>Non-chemical management:</b> '+esc(x.Chemical_Free_or_Nonchemical_Management)+'</p><p><b>Follow-up:</b> '+esc(x.Follow_Up_Monitoring)+'</p><p><b>Fertilizer / treatment note:</b> Dataset does not establish a safe fertilizer or pesticide dose; use soil-test and local extension recommendations.</p><small>'+esc(x.Dataset_Status||'Reference record')+'</small></article>').join('')+'<p class="notice">'+esc(d.notice)+'</p>'}catch(err){out.textContent='Could not search the bundled dataset. Ensure the FastAPI backend is running. '+err.message}});
  $('recommendationSearch')?.addEventListener('submit',async e=>{e.preventDefault();const crop=$('recommendCrop').value.trim(),dist=$('recommendDistrict').value.trim(),out=$('recommendationResults');out.textContent='Searching shared farmer recommendations…';try{const params=new URLSearchParams();if(crop)params.set('crop',crop);if(dist)params.set('district',dist);const response=await fetch('/api/farmer-practices?'+params.toString());if(!response.ok)throw new Error('Shared database unavailable');const data=await response.json();const matches=data.records||[];out.innerHTML=matches.length?matches.map(x=>'<article class="panel" style="margin-top:8px"><h3>'+esc(x.title||'Farmer practice')+'</h3><p><b>Crop:</b> '+esc(x.crop||'General')+' · <b>Location:</b> '+esc([x.village,x.district,x.state].filter(Boolean).join(', ')||'Not provided')+'</p><p>'+esc(x.text||'')+'</p><p><b>Shared by:</b> '+esc(x.author_label||'Farmer')+' · <b>Evidence / safety:</b> '+esc(x.safety||'Not provided')+'</p><small>'+esc(x.created_at||'')+'</small></article>').join('')+'<p class="notice">'+esc(data.notice||'Farmer reports are not verified agronomic advice.')+'</p>':'No matching shared farmer practices yet. Add a practice in Farmer Knowledge Exchange.'}catch(err){out.textContent='Could not reach the shared recommendations service. Check that the backend is running. '+err.message}});
  // Show the 15-day forecast returned by the backend and label wind/rain data per day.
  const forecastEl=$('liveForecast');if(forecastEl){const observer=new MutationObserver(()=>{const cards=[...forecastEl.children];if(cards.length>7)forecastEl.previousElementSibling?.querySelector('h3')&&(forecastEl.previousElementSibling.querySelector('h3').textContent='15-day forecast')});observer.observe(forecastEl,{childList:true,subtree:true});}
})();


