(function(){
 const $=id=>document.getElementById(id);
 const esc2=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const states=['Andhra Pradesh','Arunachal Pradesh','Assam','Bihar','Chhattisgarh','Goa','Gujarat','Haryana','Himachal Pradesh','Jharkhand','Karnataka','Kerala','Madhya Pradesh','Maharashtra','Manipur','Meghalaya','Mizoram','Nagaland','Odisha','Punjab','Rajasthan','Sikkim','Tamil Nadu','Telangana','Tripura','Uttar Pradesh','Uttarakhand','West Bengal','Andaman and Nicobar Islands','Chandigarh','Dadra and Nagar Haveli and Daman and Diu','Delhi','Jammu and Kashmir','Ladakh','Lakshadweep','Puducherry'];
 ['bookState','weatherState'].forEach(id=>{const el=$(id);if(el){const first=el.options[0]?.outerHTML||'<option value="">Choose state</option>';el.innerHTML=first+states.map(x=>`<option>${esc2(x)}</option>`).join('')}});
 async function districts(state,select){const local=dhartrixLocalDistricts(state);if(local.length){select.innerHTML='<option value="">Choose district</option>'+local.map(x=>'<option>'+esc2(x)+'</option>').join('');return;}select.innerHTML='<option value="">Loading districts…</option>';try{let data=window.__indiaDistrictData;if(!data){const r=await fetch('https://raw.githubusercontent.com/CodingMation/indian-states-districts/main/data/india_states_districts.min.json');if(!r.ok)throw Error('District service unavailable');data=await r.json();window.__indiaDistrictData=data}const norm=x=>String(x||'').toLowerCase().replace(/\s*\(ut\)/g,'').trim();let arr=[];if(Array.isArray(data)){const item=data.find(x=>norm(x.name||x.state||x.state_name)===norm(state));arr=item?.districts||[]}else if(data.states){const item=data.states.find(x=>norm(x.name||x.state||x.state_name)===norm(state));arr=item?.districts||[]}else if(data[state])arr=data[state].districts||data[state];arr=arr.map(x=>typeof x==='string'?x:(x.name||x.district||x.district_name||'')).filter(Boolean);if(!arr.length)throw Error('No district list returned');select.innerHTML='<option value="">Choose district</option>'+arr.sort().map(x=>`<option>${esc2(x)}</option>`).join('')}catch(e){select.innerHTML='<option value="">District list unavailable — enter district in village field</option>'}}
 $('bookState')?.addEventListener('change',()=>districts($('bookState').value,$('bookDistrict')));
 // Weather district suggestions from geocoding results; the place search still works without them.
 const weatherDistrictInput=$('weatherDistrict'), weatherDistrictList=$('weatherDistrictSuggestions');
 let weatherDistrictTimer=null;
 $('weatherPlace')?.addEventListener('input',()=>{clearTimeout(weatherDistrictTimer);const place=$('weatherPlace').value.trim();const state=$('weatherState')?.value||'';if(place.length<2||!weatherDistrictList)return;weatherDistrictTimer=setTimeout(async()=>{try{const r=await fetch('/api/places?q='+encodeURIComponent([place,$('weatherDistrict')?.value,state,'India'].filter(Boolean).join(', ')));if(!r.ok)return;const rows=await r.json();weatherDistrictList.innerHTML=[...new Set(rows.map(x=>x.district).filter(Boolean))].map(x=>'<option value="'+esc2(x)+'"></option>').join('');if(rows[0]?.state&&$('weatherState'))$('weatherState').value=rows[0].state;}catch{/* manual search remains available */}},450);});

 // Online locality suggestions while typing; this is not a complete offline village census.
 const villageInput=$('bookVillage'), villageList=$('indiaVillageSuggestions'); let villageTimer=null;
 villageInput?.addEventListener('input',()=>{ clearTimeout(villageTimer); const q=[villageInput.value,$('bookDistrict')?.value,$('bookState')?.value,'India'].filter(Boolean).join(', '); if(q.replace(/,/g,' ').trim().length<3||!villageList)return; villageTimer=setTimeout(async()=>{try{const r=await fetch('/api/places?q='+encodeURIComponent(q));if(!r.ok)return;const rows=await r.json();villageList.innerHTML=rows.map(x=>'<option value="'+esc2(x.village||x.name||'')+'">'+esc2([x.district,x.state].filter(Boolean).join(', '))+'</option>').join('')}catch{/* suggestions are optional; manual entry remains available */}},500); });


 $('bookGpsBtn')?.addEventListener('click',()=>{const status=$('bookLocationStatus');if(!navigator.geolocation){status.textContent='GPS is not supported by this browser.';return}status.textContent='Requesting GPS permission…';navigator.geolocation.getCurrentPosition(async pos=>{const lat=pos.coords.latitude,lon=pos.coords.longitude;$('bookGps').value=lat.toFixed(6)+', '+lon.toFixed(6);status.textContent='GPS captured. Looking up village and district…';try{const r=await fetch(`/api/places?q=${encodeURIComponent(lat+', '+lon)}`);if(r.ok){const rows=await r.json();if(rows[0]){$('bookVillage').value=rows[0].village||rows[0].name||'';if(rows[0].state){$('bookState').value=rows[0].state;await districts(rows[0].state,$('bookDistrict'))}if(rows[0].district)$('bookDistrict').value=rows[0].district}}status.textContent='GPS captured. Confirm the village and district before saving.'}catch{status.textContent='GPS captured. Enter village and district manually if lookup is unavailable.'}},e=>status.textContent='GPS unavailable: '+e.message+'; enter location manually.',{enableHighAccuracy:true,timeout:15000})});
 // Existing form expects a combined location string; preserve compatibility with the current request handler.
 $('sensorBookingForm')?.addEventListener('submit',()=>{const district=$('bookDistrict')?.value||'';const village=$('bookVillage')?.value||'';if($('bookLocation'))$('bookLocation').value=[district,village].filter(Boolean).join(', ');if($('bookState')&&$('bookState').tagName==='SELECT'){} });
 // Weather search is handled by the resilient geocoding fallback appended below.
 // Crop-aware organic practice checklist: no fabricated chemical quantities; dose is based on soil test and local label.
 const org=$('organicForm');if(org)org.addEventListener('submit',()=>{setTimeout(()=>{const crop=$('organicCrop')?.value.trim();const out=$('organicResult');if(!crop||!out)return;const c=crop.toLowerCase();let extra=[];if(/rice|paddy/.test(c))extra=['Rice/paddy focus: use healthy seed, suitable nursery/spacing, field drainage and locally recommended water management.','For nutrient needs, use a soil test and local rice nutrient recommendations; avoid applying fresh manure directly to seedlings.'];else if(/tomato|chilli|pepper|potato|brinjal|eggplant/.test(c))extra=['Vegetable focus: rotate away from related host crops when disease history suggests it, use clean planting material and avoid prolonged leaf wetness.','Compost/manure quantity varies with maturity, nutrient content and soil test; do not use a universal chemical or fertilizer dose.'];else if(/wheat|maize|corn|millet|ragi|sorghum/.test(c))extra=['Cereal focus: use locally adapted seed, rotate crops and manage residues; inspect for weeds and pests at the crop stage recommended by local extension staff.','Base nutrient additions on soil analysis and locally published crop recommendations, not symptom appearance alone.'];else if(/banana|mango|coconut|coffee|tea/.test(c))extra=['Perennial/orchard focus: maintain mulch away from the trunk, keep drainage clear and monitor the root zone and canopy regularly.','Nutrient and organic-input quantities depend on plant age, spacing, soil/tissue tests and local recommendations.'];else extra=['Crop-specific focus: confirm variety, crop stage, spacing and local season before selecting inputs.','Use mature compost and locally permitted inputs only; calculate quantities from a soil test and official crop guidance.'];out.insertAdjacentHTML('beforeend','<h4>Crop-specific checklist for '+esc2(crop)+'</h4><ol>'+extra.map(x=>'<li>'+esc2(x)+'</li>').join('')+'</ol><p class="notice">No pesticide or fertilizer dose is invented here. Exact rates must match a soil test, product label, crop stage and local agricultural guidance.</p>')},0)});
 // Make language setting persist from registration/profile and keep assistant context aligned.
 const lang=$('language');if(lang){const old=lang.onchange;lang.addEventListener('change',()=>{try{localStorage.setItem('dhartrix_language',lang.value)}catch{};const prof=(()=>{try{return JSON.parse(localStorage.getItem('dhartrix_farmer_profile')||'{}')}catch{return {}}})();prof.language=lang.value;try{localStorage.setItem('dhartrix_farmer_profile',JSON.stringify(prof))}catch{}})}
 const reg=$('registerForm');reg?.addEventListener('submit',()=>{try{localStorage.setItem('dhartrix_language',$('regLanguage')?.value||'English')}catch{}});
 // Do not translate automatically on startup; apply only when the farmer selects a language or after login using the profile preference.
})();


// Cyclone warning status: a failed check is never displayed as "no warning".
async function checkCycloneStatus(){
 const el=document.getElementById('cycloneStatus');
 const btn=document.getElementById('checkCycloneBtn');
 if(!el)return;
 el.textContent='Checking official IMD pages…'; if(btn)btn.disabled=true;
 try{
  const response=await fetch('/api/cyclone-warning');
  if(!response.ok)throw new Error('Status service unavailable');
  const data=await response.json();
  el.replaceChildren();
  const strong=document.createElement('strong');
  if(data.status==='no_active_warning_detected') strong.textContent='No active cyclone warning detected on the checked IMD landing pages.';
  else if(data.status==='check_official_bulletin') strong.textContent='Cyclone-related information found — check the official bulletin for an active warning in your area.';
  else strong.textContent='Unable to verify cyclone warnings right now.';
  el.appendChild(strong);
  const p=document.createElement('p');p.textContent=data.message||'';el.appendChild(p);
  if(data.checked_at){const small=document.createElement('small');small.textContent='Checked at '+new Date(data.checked_at).toLocaleString();el.appendChild(small)}
  const list=document.createElement('ul');
  for(const source of (data.sources||[])){const li=document.createElement('li');const a=document.createElement('a');a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=source.url;li.appendChild(a);list.appendChild(li)}
  if(list.children.length)el.appendChild(list);
 }catch(err){el.textContent='Unable to verify cyclone warnings right now. Please check the latest official IMD bulletin.'}
 finally{if(btn)btn.disabled=false}
}
document.getElementById('checkCycloneBtn')?.addEventListener('click',checkCycloneStatus);


