  [['regVillage','regVillageOptions'],['profileVillage','profileVillageOptions'],['recommendDistrict','recommendDistrictOptions'],['nutField','nutFieldOptions']].forEach(([a,b])=>addDatalist(a,b));
  const suggestionTargets=[['regVillage','regVillageOptions','regDistrict','regState'],['profileVillage','profileVillageOptions','profileDistrict','profileState'],['recommendDistrict','recommendDistrictOptions',null,'weatherState'],['nutField','nutFieldOptions',null,'weatherState']];
  // The selected weather state/district provide context for shared autocomplete requests.
  suggestionTargets.forEach(([inputId,listId,districtId,stateId])=>{const input=$id(inputId),list=$id(listId);if(!input||!list)return;let timer;input.addEventListener('input',()=>{clearTimeout(timer);const value=input.value.trim();if(value.length<2)return;timer=setTimeout(async()=>{try{const state=$id(stateId)?.value||gs?.value||'';const district=$id(districtId)?.value||gd?.value||'';const r=await fetch('/api/places?q='+encodeURIComponent([value,district,state,'India'].filter(Boolean).join(', ')));if(!r.ok)return;const rows=await r.json();list.innerHTML=rows.map(x=>'<option value="'+esc2(x.village||x.name||'')+'"></option>').join('');}catch{}},450);});});
  // Weather district becomes a true select populated from the chosen state's place results.
