    'Andhra Pradesh': {'Anantapuramu':['Anantapuramu','Gooty','Tadipatri','Uravakonda'],'Guntur':['Guntur','Tenali','Mangalagiri'],'Kurnool':['Kurnool','Adoni','Nandyal'],'Visakhapatnam':['Visakhapatnam','Anakapalle','Bheemunipatnam'],'Tirupati':['Tirupati','Srikalahasti','Chandragiri'],'Chittoor':['Chittoor','Palamaner','Madanapalle']},
    'Tamil Nadu': {'Chennai':['Chennai','Tambaram','Avadi'],'Coimbatore':['Coimbatore','Pollachi','Mettupalayam'],'Madurai':['Madurai','Melur','Thirumangalam'],'Salem':['Salem','Attur','Mettur'],'Tiruchirappalli':['Tiruchirappalli','Srirangam','Manapparai']},
    'Telangana': {'Hyderabad':['Hyderabad','Secunderabad','Serilingampally'],'Warangal':['Warangal','Hanamkonda','Kazipet'],'Karimnagar':['Karimnagar','Huzurabad']},
    'Maharashtra': {'Pune':['Pune','Pimpri-Chinchwad','Baramati'],'Nagpur':['Nagpur','Kamptee'],'Nashik':['Nashik','Malegaon','Sinnar'],'Mumbai Suburban':['Mumbai','Andheri','Borivali']},
