  function fillSelect(el, list, placeholder){ if(!el)return; const old=el.value; el.innerHTML='<option value="">'+esc(placeholder)+'</option>'+list.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join(''); if(list.includes(old))el.value=old; }
  function districtsFor(state){return districtData[state]||[];}
