    ['regState','profileState','bookState','dashState','weatherState','globalState'].forEach(id=>initStateSelect(id,id==='globalState'?'Choose state':'Choose state / UT'));
    initDistrictSelect('regState','regDistrict','regVillage');
    initDistrictSelect('profileState','profileDistrict','profileVillage');
    initDistrictSelect('bookState','bookDistrict','bookVillage');
